entries[31063] = { ["name"] = "Anhänger des Tauens", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nTeufelsstahlbarren (2), Urfeuer (6), Urwasser (4), Quecksilberadamantit\nAnhänger des Tauens\nWird beim Anlegen gebunden\nHals\n+18 Ausdauer\n+30 Frostwiderstand\n70\nBenutzen: Absorbiert von allen nahen Gruppenmitgliedern 900 bis 2700 Frostschaden. Hält 5 Min. lang an. (1 Stunde Abklingzeit)\n10 Aufladungen" }
entries[31064] = { ["name"] = "Anhänger des Erlöschens", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nTeufelsstahlbarren (2), Urschatten (6), Urleben (4), Quecksilberadamantit\nAnhänger des Erlöschens\nWird beim Anlegen gebunden\nHals\n+18 Ausdauer\n+30 Naturwiderstand\n70\nBenutzen: Absorbiert 900 bis 2700 Naturschaden, den in der Nähe befindliche Gruppenmitglieder erleiden. Hält 5 Min. lang an. (1 Stunde Abklingzeit)\n10 Aufladungen" }
entries[31065] = { ["name"] = "Anhänger der Schattenneige", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nTeufelsstahlbarren (2), Urleben (6), Urschatten (4), Quecksilberadamantit\nAnhänger der Schattenneige\nWird beim Anlegen gebunden\nHals\n+18 Ausdauer\n+30 Schattenwiderstand\n70\nBenutzen: Absorbiert 900 bis 2700 Schattenschaden, den in der Nähe befindliche Gruppenmitglieder erleiden. Hält 5 Min. lang an. (1 Stunde Abklingzeit)\n10 Aufladungen" }
entries[31066] = { ["name"] = "Anhänger der Nullrune", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nTeufelsstahlbarren (2), Urmana (8), Quecksilberadamantit\nAnhänger der Nullrune\nWird beim Anlegen gebunden\nHals\n+18 Ausdauer\n+30 Arkanwiderstand\n70\nBenutzen: Absorbiert 900 bis 2700 Arkanschaden, den in der Nähe befindliche Gruppenmitglieder erleiden. Hält 5 Min. lang an. (1 Stunde Abklingzeit)\n10 Aufladungen" }
entries[31067] = { ["name"] = "Dicke Teufelsstahlhalskette", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nTeufelsstahlbarren (2), Quecksilberadamantit (3)\nDicke Teufelsstahlhalskette\nWird beim Anlegen gebunden\nHals\n+36 Ausdauer\nErhöht Eure PvP-Abhärtungswertung um + 23.\n70\nBenutzen: Erhöht die Ausdauer naher Gruppenmitglieder 30 Min. lang um 20. (1 Stunde Abklingzeit)\n10 Aufladungen" }
entries[31068] = { ["name"] = "Lebendiger Rubinanhänger", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nKhoriumbarren (4), Quecksilberadamantit , Lebendiger Rubin\nLebendiger Rubinanhänger\nWird beim Anlegen gebunden\nHals\n+35 Ausdauer\n+16 Intelligenz\n+16 Willenskraft\n70\nBenutzen: Stellt 30 Min. lang pro Sekunde 6 Gesundheit aller in der Nähe befindlichen Gruppenmitglieder wieder her. (1 Stunde Abklingzeit)\n10 Aufladungen" }
entries[31069] = { ["name"] = "Kopfwäsche", ["text"] = "45 Meter Reichweite\nSofort\nDas Ziel vergisst, was es sagen wollte, und wird 4 Sek. lang zum Schweigen gebracht." }
entries[31070] = { ["name"] = "Geflochtene Eterniumkette", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nEterniumbarren (2), Quecksilberadamantit (3)\nGeflochtene Eterniumkette\nWird beim Anlegen gebunden\nHals\nErhöht Eure Trefferwertung um + 21.\n70\nAnlegen: +5 Waffenschaden.\nBenutzen: Erhöht den kritischen Trefferwert naher Gruppenmitglieder 30 Min. lang um 28. (1 Stunde Abklingzeit)\n10 Aufladungen" }
entries[31071] = { ["name"] = "Auge der Nacht", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nGehärteter Adamantitbarren (2), Quecksilberadamantit (2), Nachtauge\nAuge der Nacht\nWird beim Anlegen gebunden\nHals\nErhöht Eure Trefferwertung um + 16.\nErhöht Eure kritische Trefferwertung um + 26.\nErhöht Eure Tempowertung um + 15.\n70\nBenutzen: Erhöht die Zaubermacht aller in der Nähe befindlichen Gruppenmitglieder 30 Min. lang um 34. (1 Stunde Abklingzeit)\n10 Aufladungen" }
entries[31072] = { ["name"] = "Zärtliche Morgenröte", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nEterniumbarren (2), Quecksilberadamantit (4), Golddraenit (2)\nZärtliche Morgenröte\nWird beim Anlegen gebunden\nHals\n+27 Ausdauer\n+19 Intelligenz\n+18 Willenskraft\n70\nBenutzen: Alle Werte naher Gruppenmitglieder werden 30 Min. lang um 10 erhöht. (1 Stunde Abklingzeit)\n10 Aufladungen" }
entries[31073] = { ["name"] = "Feuersbrunst", ["text"] = "Verursacht beim Ziel Verwirrung, wenn es mit mächtigen Feuerzaubern angegriffen wird." }
entries[31075] = { ["name"] = "Brennendes Stroh", ["text"] = "Sofort\nIhr brennt!" }
entries[31076] = { ["name"] = "Kette der Nebeleule", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nKhoriumbarren (2), Quecksilberadamantit (4), Azurmondstein (2)\nKette der Nebeleule\nWird beim Anlegen gebunden\nHals\n+29 Ausdauer\n+18 Intelligenz\n+ 18 Ausweichen\n70\nBenutzen: Erhöht den kritischen Trefferwert naher Gruppenmitglieder 30 Min. lang um 45. (1 Stunde Abklingzeit)\n10 Aufladungen" }
entries[31077] = { ["name"] = "Kronenreif der grünen Flamme", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nKhoriumbarren (20), Urleben (20), Talasit (2), Quecksilberadamantit (5)\nKronenreif der grünen Flamme\nWird beim Anlegen gebunden\nKopf Stoff\n306 Rüstung\n+36 Ausdauer\n+40 Intelligenz\nHaltbarkeit 100 / 100\n70\nAnlegen: Chance bei erfolgreichem Zauberwirken im Verlauf von 10 Sek. 90 Mana wiederherzustellen. (Procchance: 75%, 25s Abklingzeit)" }
entries[31078] = { ["name"] = "Reif der arkanen Macht", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nTeufelsstahlbarren (20), Urmana (20), Stern der Elune (2), Quecksilberadamantit (5)\nReif der arkanen Macht\nWird beim Anlegen gebunden\nKopf Stoff\n306 Rüstung\n+39 Ausdauer\n+27 Intelligenz\n+27 Willenskraft\nHaltbarkeit 100 / 100\n70\nAnlegen: Chance von 2%, bei erfolgreichem Zauberwirken die Zaubermacht 15 Sek. lang um bis zu 120 zu erhöhen. (Procchance: 2%)" }
entries[31079] = { ["name"] = "Figur - Teufelsstahleber", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nTeufelsstahlbarren (8), Blutgranat (2), Urerde (4)\nFigur - Teufelsstahleber\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+ 68 Angriffskraft.\n70\nBenötigt Juwelierskunst\n(370)\nBenutzen: Beschwört einen Teufelsstahleber, der 30 Sek. lang für Euch kämpft. (5 Min Abklingzeit)" }
entries[31080] = { ["name"] = "Figur - Dämmersteinkrebs", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nKhoriumbarren (4), Dämmerstein (2), Golddraenit (4)\nFigur - Dämmersteinkrebs\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+ 32 Ausweichen\n70\nBenötigt Juwelierskunst\n(370)\nBenutzen: Erhöht das Ausweichen 20 Sek. lang um 153 . (2 Min Abklingzeit)" }
entries[31081] = { ["name"] = "Figur - Lebendige Rubinschlange", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nTeufelsstahlbarren (2), Lebendiger Rubin (2), Urfeuer (4)\nFigur - Lebendige Rubinschlange\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+33 Ausdauer\n+23 Intelligenz\n70\nBenötigt Juwelierskunst\n(370)\nBenutzen: Erhöht die Zaubermacht 20 Sek. lang um 183 . (5 Min Abklingzeit)" }
entries[31082] = { ["name"] = "Figur - Talasiteule", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nEterniumbarren (2), Talasit (2), Urmana (4)\nFigur - Talasiteule\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+36 Willenskraft\n70\nBenötigt Juwelierskunst\n(370)\nBenutzen: Stellt im Verlauf von 12 Sek. insgesamt 1100 Mana wieder her. (5 Min Abklingzeit)" }
entries[31083] = { ["name"] = "Figur - Nachtaugenpanther", ["text"] = "Wirken in 10 sek.\nTools: Juweliersset\nReagenzien:\nGehärteter Adamantitbarren (6), Nachtauge (2), Urschatten (2)\nFigur - Nachtaugenpanther\nWird beim Aufheben gebunden\nEinzigartig anlegbarSchmuck\n+ 54 Angriffskraft.\n70\nBenötigt Juwelierskunst\n(370)\nBenutzen: Erhöht die Angriffskraft 12 Sek. lang um 391 . (3 Min Abklingzeit)" }
