entries[31112] = { ["name"] = "Geläutertes Nachtauge", ["text"] = "Wirken in 5 sek.\nTools: Juweliersset\nReagenzien:\nNachtauge\nGeläutertes Nachtauge\n+ 4 Intelligenz und + 8 Willenskraft\n\"Am besten für einen roten oder blauen Sockel geeignet.\"" }
