entries[31114] = { ["name"] = "Medivhs Tagebuch", ["text"] = "10 Meter Reichweite\nWirken in 1 sek.\nLest die markierte Seite am südlichen Ende der Terrasse des Meisters." }
entries[31115] = { ["name"] = "Anspornender Schrei", ["text"] = "Sofort\nRuft alle Blutelfen zusammen, um die Man'ari zu unterstützen." }
entries[31116] = { ["name"] = "Nachtheuler beschwören", ["text"] = "10 Meter Reichweite\nWirken in 1 sek.\nBeschwört Schrecken der Nacht am südlichen Ende der Terrasse des Meisters." }
entries[31117] = { ["name"] = "Instabiles Gebrechen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchattenenergie zerstört langsam das Ziel. Verursacht im Verlauf von 14 Sek. insgesamt 2168 Schaden.\n\nWird 'Instabiles Gebrechen' gebannt, fügt der Zauber dem Bannenden ( 310 * 8) Schaden zu, der immer kritisch trifft. Außerdem wird der Bannende 4 Sek. lang zum Schweigen gebracht." }
entries[31118] = { ["name"] = "Ekliptik markieren", ["text"] = "Wirken in 5 sek.\nMarkiert die Ekliptik von Azeroth auf der Sternenkarte." }
entries[31120] = { ["name"] = "Konstellationen eintragen", ["text"] = "Wirken in 5 sek.\nTrägt sichtbare Konstellationen auf der Sternenkarte ein." }
entries[31121] = { ["name"] = "Planetenbahnen einzeichnen", ["text"] = "Wirken in 5 sek.\nZeichnet die Bahnen verschiedener Himmelskörper auf der Sternenkarte ein." }
entries[31149] = { ["name"] = "Funkelnder Stern der Elune", ["text"] = "Wirken in 5 sek.\nTools: Juweliersset\nReagenzien:\nStern der Elune\nFunkelnder Stern der Elune\n+ 16 Willenskraft\n\"Am besten für einen blauen Sockel geeignet.\"" }
entries[31206] = { ["name"] = "Angriffskraft - Tiergestalt (+0080)", ["text"] = "Benötigt Katzengestalt, Bärengestalt, Terrorbärengestalt, Mondkingestalt\nErhöht die Angriffskraft in Katzen-, Bären- oder Mondkingestalt um 80." }
entries[31209] = { ["name"] = "Flinken Fußes", ["text"] = "Erhöht Euer Bewegungstempo um 15%. Dieser Effekt ist mit den meisten anderen Effekten, die das Bewegungstempo erhöhen, nicht stapelbar." }
entries[31210] = { ["name"] = "Lichtenergie sammeln", ["text"] = "20 Meter Reichweite\nSofort\nEntzieht den kränklichen Magistern der Blutelfen unterhalb des Blutrittersanktums die restliche Lichtenergie." }
entries[31220] = { ["name"] = "Finstere Berufung", ["text"] = "Erhöht Eure gesamte Beweglichkeit um 30%." }
entries[31223] = { ["name"] = "Meister des hinterhältigen Angriffs", ["text"] = "Angriffe, die aus dem Verstohlenheitsmodus und bis zu 6 Sekunden nach Verlassen des Verstohlenheitsmodus ausgeführt werden, verursachen 10% zusätzlichen Schaden." }
entries[31224] = { ["name"] = "Mantel der Schatten", ["text"] = "Sofort 1 min Abklingzeit\nEntfernt sofort alle wirkenden schädlichen Zaubereffekte, gewährt momentane Immunität gegen magischen Schaden sowie schädliche Effekte [ Glyphe 'Mantel der Schatten' : verringert den erlittenen körperlichen Schaden um 40% ] und lässt Euch allen Zaubern widerstehen. Hält 5 Sek. lang an. Effekte, die den Einsatz von 'Mantel der Schatten' verhindern, können nicht entfernt werden." }
entries[31225] = { ["name"] = "Schimmerndes Gefäß", ["text"] = "40 Meter Reichweite\nWirken in 10 sek.\nBenutzt die im Gefäß gespeicherte Magie, um Sangrias Stillstreich ins Leben zurück zu holen." }
entries[31230] = { ["name"] = "Von der Schippe springen", ["text"] = "Ein Angriff, der Euch normalerweise töten würde, verringert Eure Gesundheit lediglich auf 10% Eurer maximalen Gesundheit, zusätzlich wird Euer erlittener Schaden 3 Sek. lang um 85% verringert. Dieser Effekt kann nur ein Mal alle 90 Sek. auftreten." }
entries[31231] = { ["name"] = "Von der Schippe springen", ["text"] = "Sofort\nIhr verfügt über eine Chance, einer Schaden zufügenden Attacke vollständig zu widerstehen, die Euch ansonsten töten würde und reduziert allen erlittenen Schaden 3 Sek. lang um 85%. Dieser Effekt kann nicht öfter als einmal pro Minute auftreten." }
entries[31249] = { ["name"] = "Eisblitz", ["text"] = "90 Mana 40 Meter Reichweite\nSofort\nSchleudert ein Geschoss aus Eis auf den Gegner, betäubt ihn, verursacht sofort 4250 bis 5750 Frostschaden und 4 Sek. lang 10000 Frostschaden." }
entries[31250] = { ["name"] = "Frostnova", ["text"] = "75 Mana 45 Meter Reichweite\nSofort\nFügt in der Nähe befindlichen Gegnern Frostschaden zu und macht sie bis zu 10 Sek. lang bewegungsunfähig." }
entries[31252] = { ["name"] = "Sondieren", ["text"] = "Wirken in 2 sek.\nDurchsucht 5 Erzbrocken eines unedlen Metalls nach wertvollen Edelsteinen. Dabei wird das Erz zerstört." }
entries[31256] = { ["name"] = "Frostrüstung", ["text"] = "150 Mana\nSofort 10 sek. Abklingzeit\nUmgibt den Zaubernden mit einer Frostschicht, die 10 Sek. lang bestehen bleibt. Das dicke Eis erhöht die Rüstung um 3000, verlangsamt das Bewegungstempo von Nahkampfangreifern um 50% und erhöht die Zeit zwischen ihren Angriffen um 25%.\n(2s Abklingzeit)" }
entries[31257] = { ["name"] = "Kälte", ["text"] = "30 Meter Reichweite\nSofort\nUnterkühlt Angreifer, verlangsamt ihr Bewegungstempo um 50% und ihr Angriffstempo um 25%." }
entries[31258] = { ["name"] = "Tod und Verfall", ["text"] = "320 Mana 40 Meter Reichweite\nWirken in 1 sek.\nRuft die bösartigen Kräfte von Tod und Verfall herbei, um in einem ausgewählten Gebiet 15 Sek. lang Schattenschaden zuzufügen." }
entries[31259] = { ["name"] = "Giftwolke", ["text"] = "30 Meter Reichweite\nSofort\nFügt 30 Sek. lang in der Nähe befindlichen Feinden alle 2 Sek. 500 Naturschaden zu." }
entries[31260] = { ["name"] = "Aura der Brillanz" }
entries[31261] = { ["name"] = "Permanentes Totstellen" }
entries[31262] = { ["name"] = "Feuerball", ["text"] = "50 Meter Reichweite\nWirken in 1.5 sek.\nFügt einem Gegner 1700 bis 2300 Feuerschaden zu." }
entries[31263] = { ["name"] = "Pyroschlag", ["text"] = "40 Meter Reichweite\nWirken in 5 sek.\nFügt einem Gegner 4625 bis 5375 Feuerschaden zu und versengt ihn 9 Sek. lang alle 3 Sek. für zusätzliche 500 Schaden." }
entries[31264] = { ["name"] = "Wasserelementare beschwören", ["text"] = "200 Mana\nWirken in 0.5 sek.\nBeschwört 3 mächtige Wasserelementare, die den Zaubernden unterstützen." }
entries[31266] = { ["name"] = "Blizzard", ["text"] = "150 Mana 30 Meter Reichweite\nWirken in 1 sek.\nRuft einen Blizzard herbei, der 10 Sek. lang anhält und Feinden im ausgewählten Gebiet alle 2 Sek. 950 bis 1050 Frostschaden zufügt." }
