entries[31821] = { ["name"] = "Aura der Hingabe", ["text"] = "Sofort 3 min Abklingzeit\nHeilig ( Hotfix - Passivfähigkeit )\nInspiriert alle Gruppen- und Schlachtzugsmitglieder im Umkreis von 40 Metern . Gewährt ihnen Immunität gegen Unterbrechungs- und Stilleeffekte und verringert sämtlichen erlittenen Magieschaden um 20%.\n\n'Aura der Hingabe' verringert außerhalb von Arenen und Schlachtfeldern zusätzlich den erlittenen körperlichen Schaden um 20%. Hält 6 Sek. lang an.\n\nSchutz, Vergeltung\nInspiriert [ Glyphe 'Aura der Hingabe' : Euch selbst / alle Gruppen- und Schlachtzugsmitglieder im Umkreis von 40 Metern]. Gewährt [ Glyphe 'Aura der Hingabe' : Euch / ihnen] Immunität gegen Unterbrechungs- und Stilleeffekte und verringert sämtlichen erlittenen Magieschaden um 20%. [ Heilig : 'Aura der Hingabe' verringert außerhalb von Arenen und Schlachtfeldern zusätzlich den erlittenen körperlichen Schaden um 20% ] Hält 6 Sek. lang an." }
entries[31827] = { ["name"] = "Heldenhafter Stoß", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nErhöht leicht den Nahkampfschaden des nächsten Angriffs." }
entries[31829] = { ["name"] = "Item - Paladin Pvp Set Retribution 4P Bonus", ["text"] = "Ihr erhaltet eine Aufladung heiliger Kraft, wenn Ihr direkten Schaden erleidet. Dieser Effekt kann nicht innerhalb von Dungeons oder auf Schlachtzügen und nur einmal alle 8 Sek. auftreten.\n(8s Abklingzeit)" }
entries[31842] = { ["name"] = "Göttliche Gunst", ["text"] = "Sofort 3 min Abklingzeit\nErhöht Euer Zaubertempo um 20% und die Chance auf einen kritischen Zaubereffekt um 20%. Hält 20 Sek. lang an." }
entries[31843] = { ["name"] = "Fieser Trick", ["text"] = "Nahkampfreichweite\nNächster Nahkampf 30 sek. Abklingzeit\nFügt einem Feind normalen Schaden plus 45 bis 51 zu und betäubt ihn 5 Sek. lang, wenn im Verstohlenheitsmodus angegriffen wird." }
entries[31848] = { ["name"] = "Schild des Templers", ["text"] = "Verringert die Abklingzeit Eurer Fähigkeit 'Zornige Vergeltung' um 20 Sek. und die Abklingzeit Eures Zaubers 'Wächter der Uralten Könige' um 40 Sek. Zudem erzeugt Euer Zauber 'Göttliche Bitte' 1 heilige Kraft." }
entries[31849] = { ["name"] = "Schild des Templers", ["text"] = "Verringert die Abklingzeit Eurer Fähigkeit 'Zornige Vergeltung' um 40 Sek. und die Abklingzeit Eures Zaubers 'Wächter der Uralten Könige' um 80 Sek. Zudem erzeugt Euer Zauber 'Göttliche Bitte' 2 heilige Kraft." }
entries[31850] = { ["name"] = "Unermüdlicher Verteidiger", ["text"] = "Sofort 3 min Abklingzeit\nVerringert den erlittenen Schaden 10 Sek. lang um 20%. Während 'Unermüdlicher Verteidiger' aktiv ist, wird der nächste Angriff, der Euch normalerweise töten würde, Euch stattdessen um 15% Eurer maximalen Gesundheit heilen." }
entries[31863] = { ["name"] = "Schildattacke", ["text"] = "150 Mana 8 - 25 Meter Reichweite\nSofort 30 sek. Abklingzeit\nStürmt auf einen Gegner zu, fügt 0 Heiligschaden zu und betäubt ihn bis Abbruch lang." }
entries[31865] = { ["name"] = "Verführung", ["text"] = "25 Mana 15 Meter Reichweite\nWirken in 0.5 sek. 6 sek. Abklingzeit\nVerführt 6 Sek. lang in der Nähe befindliche gegnerische Ziele." }
entries[31866] = { ["name"] = "Kreuzzug", ["text"] = "Erhöht den verursachten Schaden Eurer Fähigkeiten 'Kreuzfahrerstoß', 'Hammer der Rechtschaffenen' und 'Urteil des Templers' um 10% sowie den Schaden und die Heilung Eures Zaubers 'Heiliger Schock' um 10%. Zudem wird, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt, die Heilung Eures nächsten Wirkens von 'Heiliges Licht' innerhalb von 8 Sek. zusätzlich um 100% erhöht." }
entries[31867] = { ["name"] = "Kreuzzug", ["text"] = "Erhöht den verursachten Schaden Eurer Fähigkeiten 'Kreuzfahrerstoß', 'Hammer der Rechtschaffenen' und 'Urteil des Templers' um 20% sowie den Schaden und die Heilung Eures Zaubers 'Heiliger Schock' um 20%. Zudem wird, wenn Ihr ein Ziel tötet, das Erfahrung oder Ehre gewährt, die Heilung Eures nächsten Wirkens von 'Heiliges Licht' innerhalb von 8 Sek. zusätzlich um 200% erhöht." }
entries[31868] = { ["name"] = "Dankgebet", ["text"] = "Wenn Ihr einen Gegner tötet, der Erfahrung oder Ehre gewährt, wird für die folgenden 8 Sek. Euer nächstes Wirken von 'Lichtblitz' einen kritischen Effekt erzielen.\n(1s Abklingzeit)" }
entries[31876] = { ["name"] = "Kommunion", ["text"] = "Eure Auren erhöhen den verursachten Schaden Eurer Gruppen- und Schlachtzugsmitglieder um 3% und Euer verursachter Schaden wird permanent um zusätzlich 2% erhöht. Zudem ruft Euer Zauber 'Richturteil' den Effekt 'Erfrischung' hervor.\n\nErfrischung - Gewährt bis zu 10 Gruppen- oder Schlachtzugsmitgliedern alle 10 Sek. Manaregeneration in Höhe von 1% ihres maximalen Manas. Hält 15 Sek. lang an." }
entries[31884] = { ["name"] = "Zornige Vergeltung", ["text"] = "Sofort 3 min Abklingzeit\nErhöht jeglichen verursachten Schaden und die hervorgerufene Heilung 20 Sek. lang um 20%. [ Glyphe 'Zornige Vergeltung' : werdet Ihr alle 2 Sek. um 1% Eurer maximalen Gesundheit geheilt ] [ Zudem ] [ Glyphe 'Fallender Rächer' : wird Eure Fallgeschwindigkeit verringert ]" }
